import os, json, numpy as np, sys

# Use read-only lineage modules
sys.path.append('storage/noesis')
try:
    import analyze_contacts as AC
except Exception:
    AC = None
try:
    import seeds_motifs as SM
except Exception:
    SM = None
try:
    import operators as OP
except Exception:
    OP = None
try:
    import operators_integration as OI
except Exception:
    OI = None

N = 26
R_MIN = 1e-6
TOL = 1e-8

def load_saved_best():
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt')
        r = np.loadtxt('storage/noesis/latest_radii.txt')
        c = np.array(c, dtype=float).reshape(N, 2)
        r = np.array(r, dtype=float).reshape(N,)
        return c, r
    except Exception:
        return None, None

def grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = [[x, y] for x in coords for y in coords]
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    r_hole = d - r0 - eps
    radii = [float(r0)] * 25 + [float(r_hole)]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)

def active_pairs_set(c, r, tol=TOL):
    if AC is None:
        return None
    _, p = AC.active_sets(c, r, tol=tol)
    s = set()
    for (i, j, _) in p:
        if i > j: i, j = j, i
        s.add((i, j))
    return s

def jaccard(a, b):
    if a is None or b is None:
        return None, None, None
    inter = a & b
    uni = a | b
    if len(uni) == 0:
        return 1.0, 0, 0
    return len(inter)/len(uni), len(inter), len(uni)

def construct_packing():
    # Baseline packing (saved best or constructive fallback)
    c0, r0 = load_saved_best()
    if c0 is None:
        c0, r0 = grid_plus_hole_seed()
    s0 = float(np.sum(r0))

    # Default: return baseline if modules unavailable
    if AC is None or OP is None or OI is None:
        return c0, r0

    # Attempt to detect crossing pairs for a QDF
    op_name = None
    c_seed, r_seed = c0.copy(), r0.copy()
    try:
        top_pairs, _ = AC.top_k_bottlenecks(c0, r0, k_pair=12, k_boundary=0)
    except Exception:
        top_pairs = []

    applied_qdf = False
    if SM is not None and top_pairs:
        cp = SM.find_crossing_pairs(c0, top_pairs)
        if cp is not None:
            (i, j), (k, l) = cp
            quad = tuple({i, j, k, l})
            try:
                c_seed, r_seed = OP.quad_diagonal_flip_seed(c0, r0, quad_idxs=quad, theta=1.5e-2)
                op_name = 'QDF'
                applied_qdf = True
            except Exception:
                applied_qdf = False

    # Fallback: Chain Shear on a short interior chain near x≈0.5
    if not applied_qdf:
        try:
            b_act, _ = AC.active_sets(c0, r0, tol=TOL)
            boundary_idx = set(i for (i, kind, _) in b_act)
            candidates = [(abs(c0[i,0] - 0.5), i) for i in range(N) if i not in boundary_idx]
            candidates.sort()
            chain = [idx for (_, idx) in candidates[:5]] if len(candidates) >= 5 else [i for i in range(5)]
            c_seed, r_seed = OP.chain_shear_seed(c0, r0, chain_idxs=chain, axis='x', amount=1.0e-2)
            op_name = 'ChainShear'
        except Exception:
            # If even fallback fails, return baseline
            return c0, r0

    # Equality‑constrained polish that preserves boundary actives (trust region around seed)
    try:
        c_opt, r_opt = OI.polish_preserving_boundary(c_seed, r_seed, tol_eq=TOL, step_c=1e-3, step_r=1e-3, maxiter=500)
    except Exception:
        c_opt, r_opt = c_seed, r_seed

    s1 = float(np.sum(r_opt))

    # Compute pair Jaccard change at tol=1e‑8
    pairs0 = active_pairs_set(c0, r0, tol=TOL)
    pairs1 = active_pairs_set(c_opt, r_opt, tol=TOL)
    J, inter, uni = jaccard(pairs0, pairs1)

    # Log experiment
    try:
        os.makedirs('storage/noesis/exports', exist_ok=True)
        exp_id = int(np.random.randint(1e9))
        log = {
            'op': op_name,
            'sum_radii_before': s0,
            'sum_radii_after': s1,
            'delta_sum_radii': s1 - s0,
            'pair_jaccard_tol1e8': J,
            'pair_intersection': inter,
            'pair_union': uni,
            'seed_valid': True
        }
        with open(f'storage/noesis/exports/bpigo_exp_{exp_id}.json', 'w') as f:
            json.dump(log, f, indent=2)
    except Exception:
        pass

    # Return the better packing by Σr
    if s1 >= s0:
        return np.array(c_opt, dtype=float), np.array(r_opt, dtype=float)
    else:
        return np.array(c0, dtype=float), np.array(r0, dtype=float)
